module Main where
import System.Environment
import System.Directory
import Control.Monad
import Text.Printf
split s = case break (== ',') s of (a,[]) -> [a]; (a,_:b) -> a:split b
json s = show (s :: String)
replace old new s | take (length old) s == old = new ++ drop (length old) s
replace old new [] = []
replace old new (c:cs) = c : replace old new cs
main :: IO ()
main = do
  [bars,out,code] <- getArgs
  input <- readFile bars
  let prices = map (read . (!!1) . split) (drop 1 (lines input)) :: [Double]
      n = length prices
  unless (n>=21 && all (\p -> p>0 && not (isNaN p || isInfinite p)) prices) (fail "Invalid public close history")
  let latest = last prices
      ret k = log (latest / (prices !! (n-1-k)))
      r5 = ret 5
      r10 = ret 10
      enter = r10 > 0.006 && r5 > 0
      units = 250 / (latest * 1.10 * 1.0005 * 1.001)
      orders = "side,quantity\n" ++ if enter then printf "buy,%.10f\n" units else ""
      approach = "v3-risk-quarter signal unchanged: enter only when 10-bar log return >0.006 and 5-bar log return >0; otherwise hold cash. Minimum 21 closes. Fixed decision-close budget 250 dollars divided by latest close*1.10*1.0005*1.001, ten-decimal units. Public closes only; volume unused. Long only, no leverage; next-close fills and seven-bar equity marking. Buffer is heuristic."
      changes = replace "CODE_REF" code "Effective match-3 round-0. Exact executable source version/hash: CODE_REF. Immediate strategy parent is preserved candidate-v3-risk-quarter.hs sha256=6b2b3ff7ce8138fe927281e306c0e7fb92b85a2bf7e4e321d94ae7de26d7e662; its parent is parent-v2-match2.hs sha256=88e8906b7523f551c6a6f9f19ba29d587b62ed5ce6c87a8fabbec5f26bc17758. Read BOTH match-2 improvement documents and the preserved own parent, candidate and full test report before selection. Select the quarter-budget candidate provisionally: relative to last live match-2 parent halve budget 500 to 250 dollars; retain r10>0.006, r5>0, 21-close warmup, 1.10 buffer, fee, slippage and rounding. No algorithmic changes relative to the tested candidate; this new executable updates metadata and current peer-tip handling only. Hypothesis inherited from offline proposal: smaller exposure limits absolute failed-rally loss, not improved predictive skill. Existing agent-run 33 dependent reused-development episodes passed the declared risk criterion, but both mean profits remained negative; upside is also reduced. Independent same-window replay unavailable. No new performance test, verified effectiveness, or future superiority claim. Prior own general public tips remain in match-2/agent-one/improvement.json; no current orders shared with peers. Peer shared_tips entry [For the other agent: separate signal quality from sizing in paired tests; lower exposure can mechanically improve drawdown without improving alpha, so report the return sacrifice as well as risk reduction.] ADOPTED: Adopted as interpretation discipline. Preserve the existing paired exposure-only experiment: mean profit -1.3252441858250719 to -0.662622092910052 dollars and maximum marked drawdown 3.1912713903428654% to 1.595635695141914%. Halving exposure also halves upside and downside; no timing or alpha improvement is established. Peer shared_tips entry [For the other agent: replay identical prefix-only decisions with next-close fills, equal warmup, fees, slippage and cash-rejection rules; otherwise execution or timing mismatches can masquerade as improvement.] ADOPTED: Adopted for evidence selection. The preserved own report compares compiled executables on identical t=20..52 prefixes, 21-close warmup, reset capital, next-close fills, 10bp fee, 5bp slippage and all-or-none cash checks. No new replay is claimed and the current seven-bar outcome is unknown. Peer shared_tips entry [For the other agent: include a disjoint-window diagnostic and explicitly label overlapping episodes dependent; nearby windows share shocks and can overstate evidence for adaptation.] ADOPTED: Adopted using the already preserved stride-seven diagnostic at t=20,27,34,41,48 with disjoint forward outcome intervals. Its means are -1.7701091581125639 versus -0.8850545791014156 dollars. The full 33 episodes overlap and are dependent reused development observations; shared prefix histories mean even the diagnostic is not independent held-out validation. No new diagnostic or effectiveness claim. Peer shared_tips entry [For the other agent: label fixed sizing buffers heuristic and count rejected fills, because unknown next-close jumps can exceed cash despite a buffer.] ADOPTED: Adopted. Retain the 1.10 sizing multiplier only as a heuristic, not a gap bound. The preserved development report counts zero rejected fills for both versions. No actual current fill or feasibility at the unknown next close is claimed; long-only and no leverage remain mandatory."
      decisions = "[{\"tip\":\"For the other agent: separate signal quality from sizing in paired tests; lower exposure can mechanically improve drawdown without improving alpha, so report the return sacrifice as well as risk reduction.\",\"decision\":\"adopted\",\"reason\":\"Adopted as interpretation discipline. Preserve the existing paired exposure-only experiment: mean profit -1.3252441858250719 to -0.662622092910052 dollars and maximum marked drawdown 3.1912713903428654% to 1.595635695141914%. Halving exposure also halves upside and downside; no timing or alpha improvement is established.\"},{\"tip\":\"For the other agent: replay identical prefix-only decisions with next-close fills, equal warmup, fees, slippage and cash-rejection rules; otherwise execution or timing mismatches can masquerade as improvement.\",\"decision\":\"adopted\",\"reason\":\"Adopted for evidence selection. The preserved own report compares compiled executables on identical t=20..52 prefixes, 21-close warmup, reset capital, next-close fills, 10bp fee, 5bp slippage and all-or-none cash checks. No new replay is claimed and the current seven-bar outcome is unknown.\"},{\"tip\":\"For the other agent: include a disjoint-window diagnostic and explicitly label overlapping episodes dependent; nearby windows share shocks and can overstate evidence for adaptation.\",\"decision\":\"adopted\",\"reason\":\"Adopted using the already preserved stride-seven diagnostic at t=20,27,34,41,48 with disjoint forward outcome intervals. Its means are -1.7701091581125639 versus -0.8850545791014156 dollars. The full 33 episodes overlap and are dependent reused development observations; shared prefix histories mean even the diagnostic is not independent held-out validation. No new diagnostic or effectiveness claim.\"},{\"tip\":\"For the other agent: label fixed sizing buffers heuristic and count rejected fills, because unknown next-close jumps can exceed cash despite a buffer.\",\"decision\":\"adopted\",\"reason\":\"Adopted. Retain the 1.10 sizing multiplier only as a heuristic, not a gap bound. The preserved development report counts zero rejected fills for both versions. No actual current fill or feasibility at the unknown next close is claimed; long-only and no leverage remain mandatory.\"}]"
      manifest = "{\"code_ref\":" ++ json code ++ ",\"approach\":" ++ json approach ++ ",\"changes\":" ++ json changes ++ ",\"peer_tip_decisions\":" ++ decisions ++ "}\n"
  createDirectoryIfMissing True out
  writeFile (out ++ "/orders.csv") orders
  writeFile (out ++ "/manifest.json") manifest
  a <- readFile (out ++ "/orders.csv")
  b <- readFile (out ++ "/manifest.json")
  unless (a==orders && b==manifest && take 1 (lines a)==["side,quantity"]) (fail "Submission readback mismatch")
  printf "Public n=%d close=%.8f r5=%.8f r10=%.8f; %s.\n" n latest r5 r10 (if enter then "buy emitted; unknown-fill risk remains" else "header-only cash hold")
  putStrLn "orders.csv and manifest.json exact-readback checked; four peer tips explicitly adopted with reasons. No new performance testing or independent verification claimed."
